var KL_BASE = 'https://klz9.com';
var KL_CLIENT_ID = 'KL9K40zaSyC9K40vOMLLbEcepIFBhUKXwELqxlwTEF';
function klSign() {
  var ts = String(Math.floor(Date.now() / 1000));
  var text = ts + '.' + KL_CLIENT_ID;
  var md = Packages.java.security.MessageDigest.getInstance('SHA-256');
  var input = new Packages.java.lang.String(text).getBytes('UTF-8');
  var bytes = md.digest(input);
  var hex = '';
  for (var i = 0; i < bytes.length; i++) {
    var v = bytes[i] & 255;
    hex += (v < 16 ? '0' : '') + v.toString(16);
  }
  return {'X-Client-Sig': hex, 'X-Client-Ts': ts};
}
function klRequest(url) {
  return url + ',' + JSON.stringify({headers: klSign()});
}
function klPlain(s) {
  return String(s == null ? '' : s).replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/\s+/g, ' ').trim();
}
function klBook(b) {
  if (!b || !b.slug || !b.name) throw Error('KissLove: missing manga slug/name');
  var gs = b.genres;
  var genres = Array.isArray(gs) ? gs.join(', ') : String(gs || '').split(',').join(', ');
  return {
    name: b.name,
    author: b.authors || '',
    kind: genres + (b.m_status === 1 ? ',完结' : ',连载'),
    cover: b.cover || '',
    intro: klPlain(b.description) + (b.other_name ? '\n\n' + b.other_name : ''),
    url: KL_BASE + '/api/manga/slug/' + encodeURIComponent(b.slug),
    latest: b.last_chapter == null ? '' : 'Chapter ' + b.last_chapter
  };
}
function klImages(obj) {
  var ignore = {
    'https://1.bp.blogspot.com/-ZMyVQcnjYyE/W2cRdXQb15I/AAAAAAACDnk/8X1Hm7wmhz4hLvpIzTNBHQnhuKu05Qb0gCHMYCw/s0/LHScan.png': 1,
    'https://s4.imfaclub.com/images/20190814/Credit_LHScan_5d52edc2409e7.jpg': 1,
    'https://s4.imfaclub.com/images/20200112/5e1ad960d67b2_5e1ad962338c7.jpg': 1
  };
  var hosts = {
    'imfaclub.com': 'j1.jfimv2.xyz',
    's2.imfaclub.com': 'j2.jfimv2.xyz',
    's4.imfaclub.com': 'j4.jfimv2.xyz',
    'ihlv1.xyz': 'j1.jfimv2.xyz',
    's2.ihlv1.xyz': 'j2.jfimv2.xyz',
    's4.ihlv1.xyz': 'j4.jfimv2.xyz',
    'h1.klimv1.xyz': 'j1.jfimv2.xyz',
    'h2.klimv1.xyz': 'j2.jfimv2.xyz',
    'h4.klimv1.xyz': 'j4.jfimv2.xyz'
  };
  var images = String(obj.content || '').split(/\r?\n/);
  var out = [];
  for (var i = 0; i < images.length; i++) {
    var img = images[i].trim();
    if (!img || ignore[img]) continue;
    var m = img.match(/^(https?:\/\/)([^\/:?#]+)(.*)$/i);
    if (m && hosts[m[2].toLowerCase()]) img = m[1] + hosts[m[2].toLowerCase()] + m[3];
    out.push('<img src="' + img.replace(/&/g, '&amp;').replace(/"/g, '&quot;') + '">');
  }
  return out.join('\n');
}
